[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>GlobalStone — Global Commercial Real Estate Services</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --navy: #0A1628;
            --navy-light: #1A2B4A;
            --teal: #0D7377;
            --teal-light: #14919B;
            --gold: #C9A227;
            --gold-light: #D4AF37;
            --white: #FFFFFF;
            --gray-50: #F8FAFC;
            --gray-100: #F1F5F9;
            --gray-200: #E2E8F0;
            --gray-300: #CBD5E1;
            --gray-400: #94A3B8;
            --gray-500: #64748B;
            --gray-600: #475569;
            --gray-700: #334155;
            --gray-800: #1E293B;
            --gray-900: #0F172A;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            color: var(--gray-800);
            line-height: 1.6;
            background: var(--white);
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        img {
            max-width: 100%;
            height: auto;
        }

        .container {
            max-width: 1280px;
            margin: 0 auto;
            padding: 0 24px;
        }

        /* Header */
        .header {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            background: var(--navy);
            z-index: 1000;
            transition: background 0.3s ease;
        }

        .header-inner {
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 72px;
        }

        .logo {
            font-size: 24px;
            font-weight: 700;
            color: var(--white);
            letter-spacing: -0.5px;
        }

        .logo span {
            color: var(--teal-light);
        }

        .nav-desktop {
            display: flex;
            align-items: center;
            gap: 32px;
        }

        .nav-link {
            color: var(--gray-300);
            font-size: 14px;
            font-weight: 500;
            padding: 24px 0;
            position: relative;
            transition: color 0.2s ease;
            cursor: pointer;
        }

        .nav-link:hover {
            color: var(--white);
        }

        .nav-link.services-trigger {
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .nav-link.services-trigger::after {
            content: '';
            width: 0;
            height: 0;
            border-left: 4px solid transparent;
            border-right: 4px solid transparent;
            border-top: 4px solid currentColor;
            transition: transform 0.2s ease;
        }

        .nav-link.services-trigger:hover::after,
        .nav-link.services-trigger.active::after {
            transform: rotate(180deg);
        }

        .nav-link-highlight {
            color: var(--gold-light);
        }

        /* Mega Menu */
        .mega-menu {
            position: absolute;
            top: 100%;
            left: 50%;
            transform: translateX(-50%) translateY(10px);
            background: var(--white);
            border-radius: 8px;
            box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s ease;
            min-width: 600px;
            padding: 32px;
        }

        .mega-menu-trigger:hover .mega-menu,
        .mega-menu-trigger.active .mega-menu {
            opacity: 1;
            visibility: visible;
            transform: translateX(-50%) translateY(0);
        }

        .mega-menu-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 32px;
        }

        .mega-menu-section h4 {
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--gray-500);
            margin-bottom: 16px;
        }

        .mega-menu-items {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .mega-menu-item {
            font-size: 14px;
            font-weight: 500;
            color: var(--gray-700);
            transition: color 0.2s ease;
        }

        .mega-menu-item:hover {
            color: var(--teal);
        }

        /* Mobile Nav Toggle */
        .mobile-nav-toggle {
            display: none;
            background: none;
            border: none;
            cursor: pointer;
            padding: 8px;
        }

        .mobile-nav-toggle span {
            display: block;
            width: 24px;
            height: 2px;
            background: var(--white);
            margin: 5px 0;
            transition: all 0.3s ease;
        }

        /* Mobile Navigation */
        .nav-mobile {
            display: none;
            position: fixed;
            top: 72px;
            left: 0;
            right: 0;
            bottom: 0;
            background: var(--navy);
            overflow-y: auto;
            padding: 24px;
        }

        .nav-mobile.active {
            display: block;
        }

        .mobile-nav-item {
            border-bottom: 1px solid var(--gray-700);
        }

        .mobile-nav-link {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 16px 0;
            color: var(--white);
            font-size: 16px;
            font-weight: 500;
            background: none;
            border: none;
            width: 100%;
            cursor: pointer;
            text-align: left;
        }

        .mobile-nav-link .arrow {
            transition: transform 0.3s ease;
        }

        .mobile-nav-link.active .arrow {
            transform: rotate(180deg);
        }

        .mobile-subnav {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease;
        }

        .mobile-subnav.active {
            max-height: 500px;
        }

        .mobile-subnav a {
            display: block;
            padding: 12px 0 12px 16px;
            color: var(--gray-400);
            font-size: 14px;
        }

        /* Hero Section */
        .hero {
            position: relative;
            min-height: 100vh;
            display: flex;
            align-items: center;
            background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%);
            overflow: hidden;
            padding-top: 72px;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect fill="none" stroke="%23ffffff" stroke-width="0.1" x="0" y="0" width="100" height="100"/></svg>');
            background-size: 50px 50px;
            opacity: 0.05;
        }

        .hero-content {
            position: relative;
            z-index: 1;
            max-width: 800px;
        }

        .hero-label {
            display: inline-block;
            background: var(--teal);
            color: var(--white);
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            padding: 8px 16px;
            border-radius: 4px;
            margin-bottom: 24px;
        }

        .hero h1 {
            font-size: clamp(36px, 5vw, 64px);
            font-weight: 700;
            color: var(--white);
            line-height: 1.1;
            margin-bottom: 24px;
            letter-spacing: -1px;
        }

        .hero p {
            font-size: 18px;
            color: var(--gray-300);
            line-height: 1.7;
            margin-bottom: 40px;
            max-width: 600px;
        }

        .btn {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 14px 28px;
            font-size: 14px;
            font-weight: 600;
            border-radius: 6px;
            transition: all 0.2s ease;
            cursor: pointer;
            border: none;
        }

        .btn-primary {
            background: var(--gold);
            color: var(--navy);
        }

        .btn-primary:hover {
            background: var(--gold-light);
            transform: translateY(-2px);
        }

        .btn-secondary {
            background: transparent;
            color: var(--white);
            border: 2px solid var(--gray-500);
        }

        .btn-secondary:hover {
            border-color: var(--white);
        }

        .btn-outline {
            background: transparent;
            color: var(--teal);
            border: 2px solid var(--teal);
        }

        .btn-outline:hover {
            background: var(--teal);
            color: var(--white);
        }

        /* Announcement Banner */
        .announcement-banner {
            background: var(--teal);
            padding: 16px 0;
        }

        .announcement-inner {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 16px;
            flex-wrap: wrap;
            text-align: center;
        }

        .announcement-banner p {
            color: var(--white);
            font-size: 14px;
            font-weight: 500;
        }

        .announcement-banner .btn {
            background: var(--white);
            color: var(--teal);
            padding: 10px 20px;
            font-size: 13px;
        }

        .announcement-banner .btn:hover {
            background: var(--gray-100);
        }

        /* About Statement */
        .about-statement {
            padding: 120px 0;
            background: var(--white);
        }

        .about-content {
            max-width: 900px;
            margin: 0 auto;
            text-align: center;
        }

        .about-statement h2 {
            font-size: clamp(28px, 4vw, 48px);
            font-weight: 700;
            color: var(--navy);
            line-height: 1.2;
            margin-bottom: 24px;
            letter-spacing: -0.5px;
        }

        .about-statement p {
            font-size: 18px;
            color: var(--gray-600);
            line-height: 1.8;
            margin-bottom: 32px;
        }

        /* Featured Insights */
        .featured-insights {
            padding: 100px 0;
            background: var(--gray-50);
        }

        .section-header {
            display: flex;
            align-items: flex-end;
            justify-content: space-between;
            margin-bottom: 48px;
            flex-wrap: wrap;
            gap: 24px;
        }

        .section-label {
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            color: var(--teal);
            margin-bottom: 8px;
        }

        .section-title {
            font-size: clamp(28px, 4vw, 40px);
            font-weight: 700;
            color: var(--navy);
            letter-spacing: -0.5px;
        }

        .featured-insights-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 32px;
        }

        .featured-insight-card {
            background: var(--white);
            border-radius: 12px;
            overflow: hidden;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .featured-insight-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
        }

        .featured-insight-image {
            height: 200px;
            background: linear-gradient(135deg, var(--navy-light) 0%, var(--navy) 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--gray-500);
            font-size: 14px;
        }

        .featured-insight-content {
            padding: 24px;
        }

        .insight-tag {
            display: inline-block;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--teal);
            margin-bottom: 12px;
        }

        .featured-insight-card h3 {
            font-size: 18px;
            font-weight: 600;
            color: var(--navy);
            line-height: 1.4;
            margin-bottom: 12px;
        }

        .featured-insight-card p {
            font-size: 14px;
            color: var(--gray-500);
        }

        /* What We Do Section */
        .what-we-do {
            padding: 120px 0;
            background: var(--white);
        }

        .what-we-do-wrapper {
            display: grid;
            grid-template-columns: 300px 1fr;
            gap: 64px;
            align-items: start;
        }

        .what-we-do-tabs {
            display: flex;
            flex-direction: column;
            gap: 4px;
            position: sticky;
            top: 100px;
        }

        .what-we-do-tab {
            display: flex;
            align-items: center;
            gap: 16px;
            padding: 16px 20px;
            background: transparent;
            border: none;
            border-radius: 8px;
            cursor: pointer;
            text-align: left;
            transition: all 0.2s ease;
            font-size: 15px;
            font-weight: 500;
            color: var(--gray-600);
        }

        .what-we-do-tab:hover {
            background: var(--gray-50);
        }

        .what-we-do-tab.active {
            background: var(--navy);
            color: var(--white);
        }

        .what-we-do-tab .tab-icon {
            width: 40px;
            height: 40px;
            display: flex;
            align-items: center;
            justify-content: center;
            background: var(--gray-200);
            border-radius: 8px;
            font-size: 18px;
        }

        .what-we-do-tab.active .tab-icon {
            background: var(--teal);
        }

        .what-we-do-content {
            display: flex;
            flex-direction: column;
            gap: 32px;
        }

        .what-we-do-panel {
            display: none;
        }

        .what-we-do-panel.active {
            display: block;
        }

        .what-we-do-panel h3 {
            font-size: 32px;
            font-weight: 700;
            color: var(--navy);
            margin-bottom: 16px;
            letter-spacing: -0.5px;
        }

        .what-we-do-panel p {
            font-size: 17px;
            color: var(--gray-600);
            line-height: 1.8;
            margin-bottom: 24px;
        }

        .what-we-do-list {
            list-style: none;
            margin-bottom: 32px;
        }

        .what-we-do-list li {
            padding: 8px 0;
            padding-left: 24px;
            position: relative;
            color: var(--gray-700);
            font-size: 16px;
        }

        .what-we-do-list li::before {
            content: '';
            position: absolute;
            left: 0;
            top: 50%;
            transform: translateY(-50%);
            width: 8px;
            height: 8px;
            background: var(--teal);
            border-radius: 50%;
        }

        /* Latest Insights */
        .latest-insights {
            padding: 100px 0;
            background: var(--gray-50);
        }

        .insights-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
            gap: 32px;
        }

        .insight-card {
            background: var(--white);
            border-radius: 12px;
            overflow: hidden;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease;
        }

        .insight-card:hover {
            transform: translateY(-4px);
        }

        .insight-image {
            height: 180px;
            background: linear-gradient(135deg, var(--navy-light) 0%, var(--teal) 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--white);
            font-size: 14px;
            font-weight: 500;
        }

        .insight-content {
            padding: 24px;
        }

        .insight-meta {
            display: flex;
            align-items: center;
            gap: 12px;
            margin-bottom: 12px;
        }

        .insight-type {
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--teal);
        }

        .insight-date {
            font-size: 12px;
            color: var(--gray-400);
        }

        .insight-card h3 {
            font-size: 18px;
            font-weight: 600;
            color: var(--navy);
            line-height: 1.4;
        }

        /* Newsletter */
        .newsletter {
            padding: 100px 0;
            background: var(--navy);
        }

        .newsletter-inner {
            max-width: 600px;
            margin: 0 auto;
            text-align: center;
        }

        .newsletter h2 {
            font-size: clamp(28px, 4vw, 40px);
            font-weight: 700;
            color: var(--white);
            margin-bottom: 16px;
            letter-spacing: -0.5px;
        }

        .newsletter p {
            font-size: 17px;
            color: var(--gray-400);
            margin-bottom: 32px;
        }

        .newsletter-form {
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
            justify-content: center;
        }

        .newsletter-form input {
            flex: 1;
            min-width: 250px;
            padding: 14px 20px;
            font-size: 15px;
            border: 2px solid var(--gray-600);
            border-radius: 6px;
            background: transparent;
            color: var(--white);
        }

        .newsletter-form input::placeholder {
            color: var(--gray-500);
        }

        .newsletter-form input:focus {
            outline: none;
            border-color: var(--teal);
        }

        /* Our Commitment */
        .our-commitment {
            padding: 120px 0;
            background: var(--white);
        }

        .commitment-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 32px;
        }

        .commitment-card {
            padding: 32px;
            background: var(--gray-50);
            border-radius: 12px;
            transition: all 0.3s ease;
        }

        .commitment-card:hover {
            background: var(--navy);
        }

        .commitment-card:hover h3,
        .commitment-card:hover p {
            color: var(--white);
        }

        .commitment-card:hover .commitment-icon {
            background: var(--teal);
            color: var(--white);
        }

        .commitment-icon {
            width: 56px;
            height: 56px;
            display: flex;
            align-items: center;
            justify-content: center;
            background: var(--white);
            border-radius: 12px;
            font-size: 24px;
            margin-bottom: 20px;
            transition: all 0.3s ease;
        }

        .commitment-card h3 {
            font-size: 20px;
            font-weight: 600;
            color: var(--navy);
            margin-bottom: 12px;
            transition: color 0.3s ease;
        }

        .commitment-card p {
            font-size: 14px;
            color: var(--gray-600);
            line-height: 1.7;
            margin-bottom: 20px;
            transition: color 0.3s ease;
        }

        .commitment-link {
            font-size: 14px;
            font-weight: 600;
            color: var(--teal);
            display: inline-flex;
            align-items: center;
            gap: 6px;
            transition: gap 0.2s ease;
        }

        .commitment-card:hover .commitment-link {
            color: var(--gold-light);
        }

        .commitment-link:hover {
            gap: 10px;
        }

        /* Footer */
        .footer {
            background: var(--navy);
            padding: 80px 0 40px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 2fr repeat(4, 1fr);
            gap: 48px;
            margin-bottom: 60px;
        }

        .footer-brand p {
            color: var(--gray-400);
            font-size: 14px;
            line-height: 1.8;
            margin-top: 20px;
            max-width: 300px;
        }

        .footer-col h4 {
            font-size: 14px;
            font-weight: 600;
            color: var(--white);
            margin-bottom: 20px;
        }

        .footer-col ul {
            list-style: none;
        }

        .footer-col li {
            margin-bottom: 12px;
        }

        .footer-col a {
            font-size: 14px;
            color: var(--gray-400);
            transition: color 0.2s ease;
        }

        .footer-col a:hover {
            color: var(--white);
        }

        .footer-bottom {
            padding-top: 40px;
            border-top: 1px solid var(--gray-700);
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 20px;
        }

        .footer-legal {
            display: flex;
            gap: 24px;
        }

        .footer-legal a {
            font-size: 13px;
            color: var(--gray-500);
        }

        .footer-legal a:hover {
            color: var(--white);
        }

        .footer-copyright {
            font-size: 13px;
            color: var(--gray-500);
        }

        /* Responsive */
        @media (max-width: 1024px) {
            .what-we-do-wrapper {
                grid-template-columns: 1fr;
            }

            .what-we-do-tabs {
                flex-direction: row;
                overflow-x: auto;
                position: static;
                gap: 8px;
                padding-bottom: 24px;
            }

            .what-we-do-tab {
                white-space: nowrap;
            }

            .footer-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (max-width: 768px) {
            .nav-desktop {
                display: none;
            }

            .mobile-nav-toggle {
                display: block;
            }

            .hero-content {
                text-align: center;
            }

            .hero p {
                margin-left: auto;
                margin-right: auto;
            }

            .hero-buttons {
                justify-content: center;
                flex-wrap: wrap;
            }

            .section-header {
                flex-direction: column;
                align-items: flex-start;
            }

            .footer-grid {
                grid-template-columns: 1fr;
            }

            .footer-bottom {
                flex-direction: column;
                text-align: center;
            }

            .footer-legal {
                flex-wrap: wrap;
                justify-content: center;
            }
        }

        /* Animations */
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .fade-in {
            animation: fadeIn 0.6s ease forwards;
        }

        /* Mobile menu animation */
        .mobile-nav-toggle.active span:nth-child(1) {
            transform: rotate(45deg) translate(5px, 5px);
        }

        .mobile-nav-toggle.active span:nth-child(2) {
            opacity: 0;
        }

        .mobile-nav-toggle.active span:nth-child(3) {
            transform: rotate(-45deg) translate(5px, -5px);
        }
    </style>
</head>
<body>
    <!-- Header -->
    <header class="header">
        <div class="container header-inner">
            <a href="index.html" class="logo">Global<span>Stone</span></a>

            <nav class="nav-desktop">
                <div class="mega-menu-trigger">
                    <a class="nav-link services-trigger" href="services.html">Services</a>
                    <div class="mega-menu">
                        <div class="mega-menu-grid">
                            <div class="mega-menu-section">
                                <h4>By Need</h4>
